"""Builders for fully synthetic, fictional Yahoo v8 chart-shaped payloads."""

from __future__ import annotations

import random
from datetime import date, datetime, time
from typing import Any
from zoneinfo import ZoneInfo


def build_yahoo_chart_payload(
    ticker: str = "SPY",
    dates: tuple[str, ...] = ("2024-01-02", "2024-01-03"),
    *,
    null_quote_positions: dict[str, tuple[int, ...]] | None = None,
    null_adjusted_positions: tuple[int, ...] = (),
    include_adjusted_close: bool = True,
    provider_error: dict[str, Any] | None = None,
    empty_result: bool = False,
    timestamp_time: time = time(9, 30),
    quote_values: dict[str, tuple[float | int | None, ...]] | None = None,
    adjusted_values: tuple[float | int | None, ...] | None = None,
) -> dict[str, Any]:
    """Build a deterministic fictional Yahoo chart payload.

    Args:
        ticker: Synthetic provider symbol.
        dates: Local market dates used for timestamps.
        null_quote_positions: Quote field names mapped to null row positions.
        null_adjusted_positions: Adjusted-close positions to set to null.
        include_adjusted_close: Whether to include the adjusted-close block.
        provider_error: Optional synthetic provider error object.
        empty_result: Whether the chart result list should be empty.
        timestamp_time: Fictional local time used to derive each epoch.
        quote_values: Optional complete fictional arrays by quote field.
        adjusted_values: Optional complete fictional adjusted-close array.

    Returns:
        A new dictionary with the Yahoo v8 chart response shape. All values
        generated by this helper are fictional and are not market observations.
    """
    if provider_error is not None:
        return {"chart": {"result": None, "error": provider_error}}
    if empty_result:
        return {"chart": {"result": [], "error": None}}

    zone = ZoneInfo("America/New_York")
    timestamps = [
        int(
            datetime.combine(
                date.fromisoformat(day), timestamp_time, tzinfo=zone
            ).timestamp()
        )
        for day in dates
    ]
    quote: dict[str, list[float | int | None]] = {
        "volume": [1_000_000 + index for index in range(len(dates))],
        "high": [102.0 + index for index in range(len(dates))],
        "close": [101.0 + index for index in range(len(dates))],
        "open": [100.0 + index for index in range(len(dates))],
        "low": [99.0 + index for index in range(len(dates))],
    }
    for field, values in (quote_values or {}).items():
        if field not in quote:
            raise ValueError(f"Unsupported quote field {field!r}.")
        if len(values) != len(dates):
            raise ValueError(f"Quote field {field!r} must match dates length.")
        quote[field] = list(values)
    for field, positions in (null_quote_positions or {}).items():
        if field not in quote:
            raise ValueError(f"Unsupported quote field {field!r}.")
        for position in positions:
            quote[field][position] = None

    indicators: dict[str, Any] = {"quote": [quote]}
    if include_adjusted_close:
        adjusted: list[float | int | None] = (
            list(adjusted_values)
            if adjusted_values is not None
            else [100.5 + index for index in range(len(dates))]
        )
        if len(adjusted) != len(dates):
            raise ValueError("adjusted_values must match dates length.")
        for position in null_adjusted_positions:
            adjusted[position] = None
        indicators["adjclose"] = [{"adjclose": adjusted}]

    result = {
        "meta": {
            "currency": None,
            "symbol": ticker,
            "exchangeName": None,
            "fullExchangeName": None,
            "instrumentType": "ETF",
            "firstTradeDate": None,
            "regularMarketTime": None,
            "hasPrePostMarketData": None,
            "gmtoffset": None,
            "timezone": None,
            "exchangeTimezoneName": "America/New_York",
            "regularMarketPrice": None,
            "regularMarketChangePercent": None,
            "fulldayPrice": None,
            "fulldayChange": None,
            "fulldayChangePercent": None,
            "fiftyTwoWeekHigh": None,
            "fiftyTwoWeekLow": None,
            "regularMarketDayHigh": None,
            "regularMarketDayLow": None,
            "regularMarketVolume": None,
            "longName": None,
            "shortName": None,
            "chartPreviousClose": None,
            "priceHint": None,
            "currentTradingPeriod": {
                period: {
                    "timezone": None,
                    "start": None,
                    "end": None,
                    "gmtoffset": None,
                }
                for period in ("pre", "regular", "post")
            },
            "dataGranularity": None,
            "range": None,
            "validRanges": None,
        },
        "timestamp": timestamps,
        "indicators": indicators,
    }
    return {"chart": {"result": [result], "error": None}}


def build_synthetic_price_series(
    length: int, *, seed: int = 0, start_price: float = 100.0
) -> tuple[float, ...]:
    """Generate a deterministic fictional price series for later tests.

    Args:
        length: Number of positive prices to produce.
        seed: Seed for a local pseudorandom generator.
        start_price: Positive initial fictional price.

    Returns:
        A tuple of synthetic prices, never sourced from market data.

    Raises:
        ValueError: If length or start_price is invalid.
    """
    if length < 1:
        raise ValueError("length must be positive.")
    if start_price <= 0:
        raise ValueError("start_price must be positive.")
    generator = random.Random(seed)
    prices = [start_price]
    for _ in range(length - 1):
        prices.append(prices[-1] * (1.0 + generator.uniform(-0.02, 0.02)))
    return tuple(prices)
